package location

import (
	_ "embed"
	"strings"
)

// metrosTSV is generated by cmd/gen-metros: every GeoNames place inside a GHS-FUA
// functional urban area, with its metro value ("Sacramento, US").
//
//go:embed metros.tsv
var metrosTSV string

type metroKey struct{ name, country, admin1 string }

var metroByPlace, metroByName = loadMetros(metrosTSV)

// loadMetros returns the exact (name, country, admin1) table and the bare-name table.
// Both follow one rule: a key is kept only when every line carrying it names the same
// metro. A bare name like "Roseville" in the US is three places in three metros, and an
// exact key repeated under two metros (two same-named places the table cannot tell
// apart) is the same ambiguity one level down — either is left out, so a line gets no
// metro rather than a guessed one.
func loadMetros(tsv string) (map[metroKey]string, map[[2]string]string) {
	exact := map[metroKey]string{}
	exactAmbiguous := map[metroKey]bool{}
	seen := map[[2]string]string{}
	ambiguous := map[[2]string]bool{}
	for _, line := range strings.Split(tsv, "\n") {
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		f := strings.Split(line, "\t")
		if len(f) != 4 {
			continue
		}
		ek := metroKey{f[0], f[1], f[2]}
		if prev, ok := exact[ek]; ok && prev != f[3] {
			exactAmbiguous[ek] = true
		}
		exact[ek] = f[3]
		k := [2]string{f[0], f[1]}
		if prev, ok := seen[k]; ok && prev != f[3] {
			ambiguous[k] = true
		}
		seen[k] = f[3]
	}
	for k := range exactAmbiguous {
		delete(exact, k)
	}
	for k := range ambiguous {
		delete(seen, k)
	}
	return exact, seen
}

// metroFor resolves one city of a location line. stated is the set of US/CA subdivision
// codes the line names. With none, the bare-name table answers. With any, it never does:
// a line that states a subdivision has said where its cities are, and a bare-name guess
// for a city those subdivisions do not place would invent a metro ("Folsom, PA; Austin,
// TX" must not yield Folsom's California metro). Each stated code is tried exactly, and
// the city resolves only when they all agree on one metro.
func metroFor(cityName, country string, stated map[string]struct{}) (string, bool) {
	name := strings.ToLower(cityName)
	if len(stated) == 0 {
		v, ok := metroByName[[2]string{name, country}]
		return v, ok
	}
	found := ""
	for code := range stated {
		v, ok := metroByPlace[metroKey{name, country, code}]
		if !ok {
			continue
		}
		if found != "" && found != v {
			return "", false
		}
		found = v
	}
	return found, found != ""
}
